    /// lawtwinKafkaModelAssignTo — ../src/model.lawspec:756
    pub fn lawtwin_kafka_model_assign_to(
        member: ls::fast::Text,
        tp: TopicPartition,
        a: ls::fast::Map<ls::fast::Text, ls::fast::List<TopicPartition>>,
    ) -> ls::Result<ls::fast::Map<ls::fast::Text, ls::fast::List<TopicPartition>>> {
        Ok({
            let it = a.clone().get(&member.clone()).cloned();
            match &it {
                None => a.clone().insert(
                    member.clone(),
                    ls::fast::List::cons(tp.clone(), ls::fast::List::nil()),
                ),
                Some(field) => {
                    let selection = field.clone();
                    a.clone().insert(
                        member.clone(),
                        ls::fast::append_list(
                            &selection.clone(),
                            &ls::fast::List::cons(tp.clone(), ls::fast::List::nil()),
                        ),
                    )
                }
            }
        })
    }

