    /// lawtwinKafkaModelValidTopicName — ../src/model.lawspec:251
    pub fn lawtwin_kafka_model_valid_topic_name(name: ls::fast::Text) -> ls::Result<bool> {
        Ok({
            let n = ls::fast::Int::from_i128(ls::fast::text_length(&name.clone()) as i128);
            ls::fast::POrd::pcmp(&n.clone(), &ls::fast::Int::from_i128(1i128)).is_ge()
                && ls::fast::POrd::pcmp(&n.clone(), &ls::fast::Int::from_i128(249i128)).is_le()
                && name.clone() != ls::fast::text(".")
                && name.clone() != ls::fast::text("..")
                && ls::regex_matches(&ls::fast::text("[a-zA-Z0-9._-]+"), &name.clone())?
        })
    }

