    /// xor32 — ../src/contract.lawspec:1106
    pub fn xor32(a: u32, b: u32) -> ls::Result<u32> {
        Ok(wrapping_u_int32(xor_bits(
            ls::fast::Int::from_i128(a as i128),
            ls::fast::Int::from_i128(b as i128),
            ls::fast::Int::Small(2147483648),
        )?)?)
    }

    /// xorBits — ../src/contract.lawspec:1110
    pub fn xor_bits(
        a: ls::fast::Int,
        b: ls::fast::Int,
        bit: ls::fast::Int,
    ) -> ls::Result<ls::fast::Int> {
        Ok(
            if ls::fast::POrd::pcmp(&bit.clone(), &ls::fast::Int::from_i128(0i128)).is_le()
                || ls::fast::POrd::pcmp(&a.clone(), &ls::fast::Int::from_i128(0i128)).is_lt()
                || ls::fast::POrd::pcmp(&b.clone(), &ls::fast::Int::from_i128(0i128)).is_lt()
            {
                ls::fast::Int::Small(0)
            } else {
                if ls::fast::POrd::pcmp(
                    &a.clone().quot(&bit.clone())?,
                    &b.clone().quot(&bit.clone())?,
                )
                .is_ne()
                {
                    bit.clone()
                } else {
                    ls::fast::Int::Small(0)
                }
                .add(&xor_bits(
                    a.clone().rem(&bit.clone())?,
                    b.clone().rem(&bit.clone())?,
                    bit.clone().quot(&ls::fast::Int::from_i128(2i128))?,
                )?)
            },
        )
    }

